trim.if:
select case when wtpd.trade_id is not null then '04' else '' end paymentStatus, bobp.ENTRUST_ID entrustId, ee.ENTRUST_STATUS entrustStatus, bobp.BID_ID bidId, ee.portfolio_id portfolioId, pp.portfolio_name portfolioName, fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.finprod_name finprodName, ee.TRADE_MARKET tradeMarket, bo.PAY_DATE payDate, bo.PAY_TYPE payType, ebp.bid_prin_amt bidPrinAmt, bobp.WIN_PRIN_AMT winPrinAmt, bobp.BID_PRICE * 100 bidPrice, bobp.WIN_PRICE * 100 winPrice, bo.BID_DATE bidDate, bobp.WIN_CPRICE winCprice from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE = wtp.YIELD
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= STR_TO_DATE(#{startDate}, '%Y-%m-%d')
and bo.BID_DATE <= STR_TO_DATE(#{endDate}, '%Y-%m-%d')

union all select bo.PAY_TYPE paymentStatus, bobp.ENTRUST_ID entrustId, ee.ENTRUST_STATUS entrustStatus, bobp.BID_ID bidId, ee.portfolio_id portfolioId, pp.portfolio_name portfolioName, fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.finprod_name finprodName, ee.TRADE_MARKET tradeMarket, bo.PAY_DATE payDate, bo.PAY_TYPE payType, ebp.bid_prin_amt bidPrinAmt, bobp.WIN_PRIN_AMT winPrinAmt, bobp.BID_PRICE * 100 bidPrice, bobp.WIN_PRICE * 100 winPrice, bo.BID_DATE bidDate, bobp.WIN_CPRICE winCprice from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win and bobp.TRADE_ID is null AND BOBP.WIN_PRICE IS NOT NULL
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= STR_TO_DATE(#{startDate}, '%Y-%m-%d')
and bo.BID_DATE <= STR_TO_DATE(#{endDate}, '%Y-%m-%d')
and bo.PAY_TYPE = #{paymentStatus}
minus select bo.PAY_TYPE paymentStatus, bobp.ENTRUST_ID entrustId, ee.ENTRUST_STATUS entrustStatus, bobp.BID_ID bidId, ee.portfolio_id portfolioId, pp.portfolio_name portfolioName, fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.finprod_name finprodName, ee.TRADE_MARKET tradeMarket, bo.PAY_DATE payDate, bo.PAY_TYPE payType, ebp.bid_prin_amt bidPrinAmt, bobp.WIN_PRIN_AMT winPrinAmt, bobp.BID_PRICE * 100 bidPrice, bobp.WIN_PRICE * 100 winPrice, bo.BID_DATE bidDate, bobp.WIN_CPRICE winCprice from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE = wtp.YIELD
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= STR_TO_DATE(#{startDate}, '%Y-%m-%d')
and bo.BID_DATE <= STR_TO_DATE(#{endDate}, '%Y-%m-%d')

union all select case when bobp.trade_id is not null then '05' else '' end paymentStatus, bobp.ENTRUST_ID entrustId, ee.ENTRUST_STATUS entrustStatus, bobp.BID_ID bidId, ee.portfolio_id portfolioId, pp.portfolio_name portfolioName, fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.finprod_name finprodName, ee.TRADE_MARKET tradeMarket, bo.PAY_DATE payDate, bo.PAY_TYPE payType, ebp.bid_prin_amt bidPrinAmt, bobp.WIN_PRIN_AMT winPrinAmt, bobp.BID_PRICE * 100 bidPrice, bobp.WIN_PRICE * 100 winPrice, bo.BID_DATE bidDate, bobp.WIN_CPRICE winCprice from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id=bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE
where 1=1 and bobp.is_win='Y' and bo.is_win = bobp.is_win AND bobp.trade_id is not NULL
AND ee.PORTFOLIO_ID IN
#{prot,jdbcType=VARCHAR}
and fp.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%'))
and ee.TRADE_MARKET=#{tradeMarket}
and ee.COUNTER_ID=#{counterId}
and bo.BID_DATE >= STR_TO_DATE(#{startDate}, '%Y-%m-%d')
and bo.BID_DATE <= STR_TO_DATE(#{endDate}, '%Y-%m-%d')
